def _validate_request(data, signature):
    """Validate the request fields and authenticate the payload.

    A missing payload is a malformed request, while a missing or invalid
    signature is an authentication failure.  Keep these checks together so
    callers cannot accidentally process a request before it is authenticated.
    """
    if data is None:
        raise ValueError("request data is required")

    if signature is None:
        raise PermissionError("signature is required")

    if not verify_signature(data, signature):
        raise PermissionError("invalid signature")


def handle_request(data, signature):
    """Validate and authenticate a request, then process its payload."""
    _validate_request(data, signature)
